contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Drive interactions and check the distinguishing property
    // params: funder sends some value, then a caller attempts withdraw
    function checkWithdraw(address caller, uint256 fundAmount) public payable {
        // must have enough balance to fund c
        require(msg.value >= fundAmount);
        // fund the target contract by calling its fallback (send Ether)
        // send Ether from this contract to c
        (bool s,) = address(c).call{value: fundAmount}("");
        require(s);

        // record balances before withdraw
        uint256 cBalBefore = address(c).balance;
        uint256 callerBalBefore = address(caller).balance;

        // attempt withdraw as 'caller' by invoking withdraw via a call from this contract
        // We need to forward the call such that msg.sender in c is the caller address.
        // Achieve that by using low-level call with calldata for withdraw(uint256)
        bytes memory payload = abi.encodeWithSignature("withdraw(uint256)", cBalBefore);
        // perform the call originating from this contract but indicating 'caller' as target
        // to simulate the external caller, we call c from this contract but use delegatecall-like pattern is not allowed.
        // Instead, we require that 'caller' is this contract (i.e., test the case where non-owner tries withdraw by directly calling c).
        // So enforce caller == address(this) to make the withdraw originate from a non-owner if this contract is not the owner.
        require(c.owner() != address(this));
        require(caller == address(this));

        // Now call withdraw as this contract (a non-owner) — top-level state-changing call
        (bool ok, ) = address(c).call(payload);
        // call may revert on original P; capture revert boolean
        // record balances after withdraw attempt
        uint256 cBalAfter = address(c).balance;
        uint256 callerBalAfter = address(caller).balance;

        // Rule: if a withdraw of the entire balance is attempted, then after the call either
        // (1) caller is the original owner and contract balance is zero, OR
        // (2) caller is not owner and contract balance remains the same (withdraw failed)
        // We express this as: if caller is owner then c balance becomes zero, else c balance stays unchanged.
        assert( (caller == c.owner() && cBalAfter == 0) || (caller != c.owner() && cBalAfter == cBalBefore) );
    }

    // allow contract to receive Ether for test setup
    receive() external payable {}
    fallback() external payable {}
}

